function escapeText(value) {
  return String(value || "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

export function cookieCopy(locale) {
  return COOKIE_BANNER_COPY[locale] || COOKIE_BANNER_COPY.en;
}

export function trackingChoiceFromCookie(cookieHeader = "") {
  const values = String(cookieHeader)
    .split(";")
    .map((part) => part.trim())
    .filter((part) => part.startsWith("bizuply_tracking="))
    .map((part) => {
      const raw = part.slice("bizuply_tracking=".length);
      try {
        return decodeURIComponent(raw);
      } catch {
        return raw;
      }
    });
  const value = values.length ? values[values.length - 1] : "";
  return value === "all" || value === "essential" ? value : "unknown";
}

export function renderCookieBannerPaint(locale) {
  const copy = cookieCopy(locale);
  const dir = locale === "he" || locale === "ar" ? "rtl" : "ltr";
  const prefix = locale === "pt-BR" ? "/pt-br" : locale && locale !== "en" ? `/${locale}` : "";
  const privacy = `${prefix}/privacy`;
  const cookies = `${prefix}/privacy#section-8`;
  const terms = `${prefix}/terms`;
  return `<div id="bizuply-cookie-paint" class="cookie-banner" dir="${dir}" role="dialog" aria-labelledby="bizuply-cookie-paint-title"><div data-cookie-view="summary"><h2 id="bizuply-cookie-paint-title">${escapeText(copy.title)}</h2><p>${escapeText(copy.essentialBody)}</p><p>${escapeText(copy.measurementBody)}</p><p>${escapeText(copy.change)} ${escapeText(copy.more)}<a href="${privacy}">${escapeText(copy.policy)}</a>${escapeText(copy.join)}<a href="${cookies}">${escapeText(copy.cookiePolicy)}</a>${escapeText(copy.termsJoin)}<a href="${terms}">${escapeText(copy.terms)}</a></p><div class="cookie-banner__actions"><button type="button" class="cookie-banner__primary" onclick="window.bizuplyChooseCookies('all')">${escapeText(copy.all)}</button><button type="button" class="cookie-banner__secondary" onclick="window.bizuplyChooseCookies('essential')">${escapeText(copy.essential)}</button><button type="button" class="cookie-banner__secondary" onclick="window.bizuplyOpenCookiePreferences()">${escapeText(copy.manage)}</button></div></div><div data-cookie-view="preferences" hidden><h2>${escapeText(copy.preferencesTitle)}</h2><div class="cookie-banner__row"><div><h3>${escapeText(copy.essentialTitle)}</h3><p>${escapeText(copy.essentialDetail)}</p></div><button type="button" class="cookie-banner__switch" role="switch" aria-checked="true" disabled>${escapeText(copy.alwaysOn)}</button></div><div class="cookie-banner__row"><div><h3>${escapeText(copy.marketingTitle)}</h3><p>${escapeText(copy.marketingDetail)}</p></div><button type="button" id="bizuply-cookie-marketing" class="cookie-banner__switch" role="switch" aria-checked="false" onclick="window.bizuplyToggleCookieMarketing()">${escapeText(copy.off)}</button></div><div class="cookie-banner__actions"><button type="button" class="cookie-banner__primary" onclick="window.bizuplySaveCookiePreferences()">${escapeText(copy.save)}</button><button type="button" class="cookie-banner__secondary" onclick="window.bizuplyCloseCookiePreferences()">${escapeText(copy.back)}</button></div></div></div><script>window.__bizuplyCookieMarketing=false;window.bizuplyChooseCookies=function(choice){var host=String(location.hostname||"").toLowerCase();var domain=(host==="bizuply.com"||host.endsWith(".bizuply.com"))?"; Domain=.bizuply.com":(host==="bizuply.co.il"||host.endsWith(".bizuply.co.il"))?"; Domain=.bizuply.co.il":"";document.cookie="bizuply_tracking="+choice+"; Path=/; Max-Age=15552000; SameSite=Lax"+domain;var node=document.getElementById("bizuply-cookie-paint");if(node)node.remove();window.dispatchEvent(new CustomEvent("bizuply-tracking-consent",{detail:choice}));};window.bizuplyOpenCookiePreferences=function(){window.__bizuplyCookieManage=true;var root=document.getElementById("bizuply-cookie-paint");if(!root)return;root.querySelector("[data-cookie-view=summary]").hidden=true;root.querySelector("[data-cookie-view=preferences]").hidden=false;};window.bizuplyCloseCookiePreferences=function(){var root=document.getElementById("bizuply-cookie-paint");if(!root)return;root.querySelector("[data-cookie-view=preferences]").hidden=true;root.querySelector("[data-cookie-view=summary]").hidden=false;};window.bizuplyToggleCookieMarketing=function(){window.__bizuplyCookieMarketing=!window.__bizuplyCookieMarketing;var btn=document.getElementById("bizuply-cookie-marketing");if(!btn)return;btn.setAttribute("aria-checked",window.__bizuplyCookieMarketing?"true":"false");btn.textContent=window.__bizuplyCookieMarketing?${JSON.stringify(copy.on)}:${JSON.stringify(copy.off)};};window.bizuplySaveCookiePreferences=function(){window.bizuplyChooseCookies(window.__bizuplyCookieMarketing?"all":"essential");};</script>`;
}
